1	import { test, expect } from './base.js';
2	import path from 'path';
3	
4	const FIXTURE = path.resolve('test/fixtures/sine-3s.mp3');
5	const BAD_FIXTURE = path.resolve('test/fixtures/bad.mp3');
6	const EMPTY_FIXTURE = path.resolve('test/fixtures/empty.mp3');
7	
8	// helper: wait for background save to persist a file to store
9	async function waitForSave(page, timeout = 10000) {
10	  await page.waitForFunction(() => !document.querySelector('#status'), { timeout });
11	  await page.waitForFunction(async () => {
12	    let { createStore } = await import('/src/store/index.js');
13	    let store = createStore();
14	    await store.init();
15	    let files = await store.getFiles();
16	    return files.length > 0;
17	  }, { timeout });
18	}
19	
20	// helper: load a file into wavearea via file input
21	async function loadFile(page, filePath = FIXTURE) {
22	  // trigger file input directly (hidden input, label clicks it)
23	  const fileInput = page.locator('input#file');
24	  await fileInput.waitFor({ state: 'attached', timeout: 5000 });
25	  const [fileChooser] = await Promise.all([
26	    page.waitForEvent('filechooser'),
27	    fileInput.dispatchEvent('click')
28	  ]);
29	  await fileChooser.setFiles(filePath);
30	  // wait for waveform to render
31	  await page.waitForFunction(() => {
32	    let el = document.querySelector('#editarea');
33	    return el && el.textContent.length > 10;
34	  }, { timeout: 15000 });
35	  // wait for loading to complete (play button appears)
36	  await page.locator('#play').waitFor({ state: 'visible', timeout: 15000 });
37	}
38	
39	
40	test.describe('wavearea', () => {
41	
42	  test.beforeEach(async ({ page }) => {
43	    await page.goto('/');
44	    // wait for sprae to initialize
45	    await page.waitForFunction(() => document.querySelector('#wavearea main, #wavearea nav, #opener nav, input#file'), { timeout: 5000 });
46	  });
47	
48	  test('renders empty state with file input', async ({ page }) => {
49	    // file input should exist (opener is rendered)
50	    await expect(page.locator('input#file')).toBeAttached();
51	    // waveform should not be visible
52	    let editarea = page.locator('#editarea');
53	    await expect(editarea).not.toBeVisible();
54	  });
55	
56	  test('loads file and renders waveform', async ({ page }) => {
57	    await loadFile(page);
58	    let text = await page.locator('#editarea').textContent();
59	    expect(text.length).toBeGreaterThan(10);
60	    // wavefont face (bundled from the npm package) actually loads
61	    expect(await page.evaluate(() => document.fonts.load('50px wavefont').then(faces => faces.length))).toBeGreaterThan(0);
62	    // play button should be visible
63	    await expect(page.locator('#play')).toBeVisible();
64	  });
65	
66	  test('clicking waveform moves caret to clicked position', async ({ page }) => {
67	    await loadFile(page);
68	
69	    let errors = [];
