779	// Web Audio spy — inject before page load to capture all AudioContext calls
780	const WEB_AUDIO_SPY = () => {
781	  window.__audioSpy = { calls: [], nodes: [], ctx: null };
782	
783	  const OrigAudioContext = window.AudioContext || window.webkitAudioContext;
784	  window.AudioContext = function(...args) {
785	    let ctx = new OrigAudioContext(...args);
786	    window.__audioSpy.ctx = ctx;
787	    window.__audioSpy.calls.push({ method: 'new AudioContext', args: args[0] || {} });
788	
789	    // spy on createBufferSource
790	    let origCreateBufferSource = ctx.createBufferSource.bind(ctx);
791	    ctx.createBufferSource = function() {
792	      let source = origCreateBufferSource();
793	      let node = { type: 'BufferSource', started: false, stopped: false, loop: false, playbackRate: 1, buffer: null };
794	      window.__audioSpy.nodes.push(node);
795	
796	      let origStart = source.start.bind(source);
797	      source.start = function(...a) {
798	        node.started = true;
799	        node.startArgs = a;
800	        window.__audioSpy.calls.push({ method: 'source.start', args: a });
801	        return origStart(...a);
802	      };
803	
804	      let origStop = source.stop.bind(source);
805	      source.stop = function(...a) {
806	        node.stopped = true;
807	        window.__audioSpy.calls.push({ method: 'source.stop', args: a });
808	        return origStop(...a);
809	      };
810	
811	      // track property changes
812	      let origBuffer = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(source), 'buffer');
813	      Object.defineProperty(source, 'buffer', {
814	        get() { return origBuffer.get.call(this); },
815	        set(v) {
816	          node.buffer = { channels: v?.numberOfChannels, length: v?.length, sampleRate: v?.sampleRate };
817	          window.__audioSpy.calls.push({ method: 'source.buffer=', buffer: node.buffer });
818	          origBuffer.set.call(this, v);
819	        }
820	      });
821	
822	      let origLoop = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(source), 'loop');
823	      Object.defineProperty(source, 'loop', {
824	        get() { return origLoop.get.call(this); },
825	        set(v) {
826	          node.loop = v;
827	          window.__audioSpy.calls.push({ method: 'source.loop=', value: v });
828	          origLoop.set.call(this, v);
829	        }
830	      });
831	
832	      return source;
833	    };
834	
835	    // spy on createGain
836	    let origCreateGain = ctx.createGain.bind(ctx);
837	    ctx.createGain = function() {
838	      let gain = origCreateGain();
839	      window.__audioSpy.calls.push({ method: 'createGain' });
840	      return gain;
841	    };
842	
843	    // spy on createBuffer
844	    let origCreateBuffer = ctx.createBuffer.bind(ctx);
845	    ctx.createBuffer = function(...a) {
846	      window.__audioSpy.calls.push({ method: 'createBuffer', args: a });
847	      return origCreateBuffer(...a);
848	    };
849	
850	    return ctx;
851	  };
852	  if (window.webkitAudioContext) window.webkitAudioContext = window.AudioContext;
853	};
