import { test, expect } from './base.js';
import path from 'path';
test('smoke: 1s wav zoom/pan', async ({ page }) => {
  await page.goto('/');
  await page.waitForFunction(() => window.wa, { timeout: 5000 });
  const fileInput = page.locator('input#file');
  const [fileChooser] = await Promise.all([page.waitForEvent('filechooser'), fileInput.dispatchEvent('click')]);
  await fileChooser.setFiles(path.resolve('asset/audio-1s.wav'));
  await page.locator('#play').waitFor({ state: 'visible', timeout: 15000 });
  console.log('LOADED', JSON.stringify(await page.evaluate(() => ({
    total: wa.total, dur: wa.duration, pps: wa.pixelsPerSecond, st: wa.scrollTime, vd: wa.viewDuration }))));
  // ctrl+wheel zoom out then in
  await page.evaluate(() => document.querySelector('#waveform').dispatchEvent(new WheelEvent('wheel', { ctrlKey: true, deltaY: 120, bubbles: true, cancelable: true })));
  await page.waitForFunction(() => wa.blockSize === 2048, { timeout: 10000 });
  await page.evaluate(() => document.querySelector('#waveform').dispatchEvent(new WheelEvent('wheel', { ctrlKey: true, deltaY: -120, bubbles: true, cancelable: true })));
  await page.waitForFunction(() => wa.blockSize === 1024, { timeout: 10000 });
  // shift+wheel pan — 1s audio must not scroll into negative time
  await page.evaluate(() => document.querySelector('#waveform').dispatchEvent(new WheelEvent('wheel', { shiftKey: true, deltaY: -2000, bubbles: true, cancelable: true })));
  await page.waitForTimeout(200);
  console.log('AFTER PAN', JSON.stringify(await page.evaluate(() => ({ st: wa.scrollTime }))));
  expect(await page.evaluate(() => wa.scrollTime)).toBe(0);
  // playback still works
  await page.keyboard.press('Control+Space');
  await page.waitForTimeout(300);
  expect(await page.evaluate(() => wa.playing)).toBe(true);
  await page.keyboard.press('Control+Space');
});
EOF
